descriptor.templateCss:
.dev-attr-filter { display:flex; flex-direction:column; height:100%; font-family:'Open Sans', Roboto, sans-serif; font-size:14px; color:#303030; background:#fff; overflow:hidden; }
.daf-toolbar { display:flex; gap:8px; padding:8px; align-items:center; flex-wrap:wrap; flex-shrink:0; }
.daf-toolbar select, .daf-toolbar input { height:32px; border:1px solid rgba(0,0,0,.2); border-radius:4px; padding:0 8px; font-size:14px; box-sizing:border-box; background:#fff; color:#333; outline:none; }
.daf-toolbar input { flex:1; min-width:120px; }
.daf-toolbar button { height:32px; padding:0 14px; border:none; border-radius:4px; cursor:pointer; background:#2e7d32; color:#fff; font-size:14px; }
.daf-toolbar .f-clear { background:#eee; color:#555; padding:0 10px; }
.daf-table-wrap { flex:1; overflow:auto; }
.daf-table { width:100%; border-collapse:collapse; }
.daf-table th, .daf-table td { text-align:left; padding:8px 12px; border-bottom:1px solid #eee; }
.daf-table th { position:sticky; top:0; background:#fafafa; font-weight:500; color:#555; }
.daf-table tbody tr { cursor:pointer; }
.daf-table tbody tr:hover { background:#f1f8f2; }
.f-count { padding:6px 12px; font-size:12px; color:#888; flex-shrink:0; }
.f-empty { padding:20px; text-align:center; color:#999; display:none; }

descriptor.controllerScript:
var self = this;

self.onInit = function() {
    var ctx = self.ctx;

    // ===================== CONFIG - edit these =====================
    self.cfg = {
        attributeKeys: ['region', 'location', 'site'],   // keys listed in the dropdown
        attributeScope: 'SERVER_ATTRIBUTE',              // SERVER_ATTRIBUTE | CLIENT_ATTRIBUTE | SHARED_ATTRIBUTE
        matchOperation: 'CONTAINS',                      // CONTAINS | EQUAL | STARTS_WITH
        pageSize: 100
    };
    // ===============================================================

    self.entityService = ctx.$scope.$injector.get(ctx.servicesMap.get('entityService'));

    var $c = ctx.$container;
    var sel = $c.find('.f-key');
    self.cfg.attributeKeys.forEach(function(k){ sel.append('<option value="' + k + '">' + k + '</option>'); });

    $c.find('.f-search').on('click', function(){ self.runQuery(); });
    $c.find('.f-value').on('keyup', function(e){ if (e.key === 'Enter') self.runQuery(); });
    $c.find('.f-clear').on('click', function(){ $c.find('.f-value').val(''); self.runQuery(); });

    self.runQuery();
};

self.runQuery = function() {
    var ctx = self.ctx, $c = ctx.$container;
    var key = $c.find('.f-key').val();
    var value = ($c.find('.f-value').val() || '').trim();

    var query = {
        entityFilter: { type: 'entityType', entityType: 'DEVICE' },
        pageLink: {
            pageSize: self.cfg.pageSize, page: 0,
            sortOrder: { key: { type: 'ENTITY_FIELD', key: 'name' }, direction: 'ASC' }
        },
        entityFields: [
            { type: 'ENTITY_FIELD', key: 'name' },
            { type: 'ENTITY_FIELD', key: 'label' }
        ],
        latestValues: [ { type: self.cfg.attributeScope, key: key } ]
    };

    if (value) {
        query.keyFilters = [{
            key: { type: self.cfg.attributeScope, key: key },
            valueType: 'STRING',
            predicate: { type: 'STRING', operation: self.cfg.matchOperation, ignoreCase: true, value: { defaultValue: value } }
        }];
    }

    self.entityService.findEntityDataByQuery(query).subscribe(
        function(pd){ self.render((pd && pd.data) || [], key); },
        function(err){ console.error('[attr-filter] query failed', err); self.render([], key); }
    );
};

self.render = function(rows, key) {
    var ctx = self.ctx, $c = ctx.$container;
    var $body = $c.find('.f-rows').empty();

    function fv(e, t, k){ try { return e.latest[t][k].value; } catch(x){ return ''; } }

    rows.forEach(function(e){
        var name = fv(e, 'ENTITY_FIELD', 'name');
        var label = fv(e, 'ENTITY_FIELD', 'label');
        var attr = fv(e, self.cfg.attributeScope, key);
        var $tr = $('<tr><td>' + esc(name) + '</td><td>' + esc(label) + '</td><td class="attr-col">' + esc(attr) + '</td></tr>');
        (function(ent, nm){ $tr.on('click', function(){ self.rowClick(ent, nm); }); })(e, name);
        $body.append($tr);
    });

    $c.find('.f-empty').css('display', rows.length === 0 ? 'block' : 'none');
    $c.find('.f-count').text(rows.length + ' device(s)');
};

self.rowClick = function(entityData, name) {
    var descriptors = self.ctx.actionsApi.getActionDescriptors('rowClick');
    if (descriptors && descriptors.length > 0) {
        self.ctx.actionsApi.handleWidgetAction({}, descriptors[0], entityData.entityId, name, null, null);
    }
};

function esc(str) {
    if (str === null || str === undefined) return '';
    return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}

self.onDestroy = function() {
    var $c = self.ctx.$container;
    $c.find('.f-search, .f-clear').off('click');
    $c.find('.f-value').off('keyup');
    $c.find('.f-rows tr').off('click');
};
